// zcode-acp quota-dock plugin v3 (seeded by zcode-acp-server, ADR-0021)
// v2: sticky last-known quota text (a mid-turn options push without the
// quota option no longer drops the node) + order:-1 so compact width
// truncation sacrifices trailing stats sections before QUOTA.
// v3: per-turn TPS — diff of usage.output / stats.llmMillis between stats
// snapshots (both cumulative, both land at turn end), so the segment shows
// the LAST turn's throughput, not a session-wide average.
return {
  inject: ["tuiSlots", "acpSessionConfig", "acpSessionStats"],
  apply: (ctx) => {
    let panel
    let quotaText = null
    let context = null
    let tps = null
    let prevStats = null
    const compactSize = (n) => {
      if (n >= 1000000) return (Math.round(n / 100000) / 10) + "M"
      if (n >= 1000) return Math.round(n / 1000) + "K"
      return String(n)
    }
    const readQuota = (options) => {
      const list = options || ctx.acpSessionConfig.list()
      const found = (list || []).filter((o) => o && o.id === "quota")[0]
      if (!found || typeof found.currentValue !== "string") return
      // Sticky: only an explicit empty string clears; a missing option keeps
      // the last-known text so full-replace pushes without quota cannot
      // erase the dock line.
      quotaText = found.currentValue.length > 0 ? found.currentValue : null
    }
    const readStats = () => {
      const cur = ctx.acpSessionStats.current ? ctx.acpSessionStats.current() : null
      const c = cur && cur.context ? cur.context : null
      context = c && typeof c.used === "number" && typeof c.size === "number" && c.size > 0 ? c : null
      const output = cur && cur.usage && typeof cur.usage.output === "number" ? cur.usage.output : null
      const llm = cur && cur.stats && typeof cur.stats.llmMillis === "number" ? cur.stats.llmMillis : null
      if (output !== null && llm !== null) {
        if (prevStats && llm > prevStats.llm && output >= prevStats.output) {
          const tok = output - prevStats.output
          const sec = (llm - prevStats.llm) / 1000
          if (tok > 0 && sec > 0) tps = Math.round(tok / sec)
        }
        prevStats = { output, llm }
      }
    }
    const nodes = () => {
      const parts = []
      if (quotaText) parts.push(quotaText)
      if (context) parts.push("ctx " + (Math.round((context.used / context.size) * 1000) / 10) + "%/" + compactSize(context.size))
      if (tps !== null) parts.push(tps + " tok/s")
      if (parts.length === 0) return []
      return [{ id: "zcode-acp-quota-gauge", kind: "generic", title: parts.join(" · "), body: "" }]
    }
    const render = () => { if (panel) { try { panel.update(nodes()) } catch (err) {} } }
    const stopSlot = ctx.tuiSlots.inject("conversation.composer.dock", () => {
      panel = ctx.tuiSlots.register({ name: "conversation.composer.dock", id: "zcode-acp-quota", order: -1 }, nodes())
      return () => panel.dispose()
    })
    readQuota()
    readStats()
    const stopSub = ctx.acpSessionConfig.subscribe((snap) => { readQuota(snap && snap.options); render() })
    let stopStats = null
    if (ctx.acpSessionStats.subscribe) stopStats = ctx.acpSessionStats.subscribe(() => { readStats(); render() })
    return () => { stopSub && stopSub(); stopStats && stopStats(); stopSlot && stopSlot() }
  },
}
